-- Resources content for Sourcework's outline (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema.

select private.rc_release_guide(
  p_slug => 'sourcework-outline',
  p_tool_key => 'transcription',
  p_title => 'Outline a piece',
  p_summary => 'Plan a piece as beats before any narration is written, then write the outline out in place.',
  p_screen_keys => array['sourcework.piece'],
  p_sort_order => 22,
  p_version_note => 'First version',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline plans a piece before any narration is written. It is a list of beats, each saying what that part of the story has to do, with your excerpts placed where they belong. You edit the outline, then write it out. Nothing is written for you until you ask."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Outline an empty piece"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open a new piece and choose "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":". Pick a format if you want its length and style as guidance, add a direction if you have one, and choose "},{"type":"text","text":"Outline the piece","marks":[{"type":"bold"}]},{"type":"text","text":". It can take a few minutes, because the model may check the transcripts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It works from the findings you have accepted, the project’s synthesis if there is one, and every excerpt the project has. The first beat is the angle: the point of the piece in a sentence."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The result is an ordinary version. Use History to go back, and edit it like any other piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Read a beat"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A beat takes no time, so the length at the top counts only narration and excerpts."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"What carries it","marks":[{"type":"bold"}]},{"type":"text","text":" opens the findings the beat rests on, with a link to listen where each was said. A finding you have since rejected is counted as no longer accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark to check","marks":[{"type":"bold"}]},{"type":"text","text":" flags a beat whose figure, name or attribution rests on one source or isn’t settled. When the outline is written out, that sentence gets a bracketed check note instead of being stated as fact."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tape","marks":[{"type":"bold"}]},{"type":"text","text":" links to a stretch of a recording the outline thought worth your attention that is not an excerpt yet. Open it, and make an excerpt if you want it in the piece."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Change the outline"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Edit a beat’s text directly. Use the + between blocks to add a narration block, an outline beat or an excerpt, and the ⋮ menu to move or remove one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The assistant can add and change beats too. Every change it makes is a version you can undo."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Write from outline"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A piece with beats shows "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":". It writes each beat out as narration, in the same place."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your excerpts, their trims, and anything you already wrote stay exactly as they are. The model cannot reorder the piece, add a clip or drop one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A beat the model leaves unwritten stays in the outline, and the page says how many. Undo returns you to the outline."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline and a draft are suggestions. Check every name, figure and attribution before you air anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An outline uses at most the 150 newest excerpts in a project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interview text and your findings are sent to an outside service, as for transcription."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-24-sourcework-outline',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-24',
  p_title => 'Sourcework: Outline a piece before you write it',
  p_guide_slugs => array['sourcework-outline'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pieces can now be outlined. On an empty piece, "},{"type":"text","text":"Outline with AI","marks":[{"type":"bold"}]},{"type":"text","text":" plans the story as beats with your excerpts placed where they belong, from the findings you have accepted. Beats take no time and can be edited, marked to check, or added by hand or by the assistant. "},{"type":"text","text":"Write from outline","marks":[{"type":"bold"}]},{"type":"text","text":" then turns each beat into narration in place and leaves your excerpts and anything you wrote alone. Both are versions you can undo."}]}]}$body$
);
